/**
 * POST /api/sky/solve/explain-stream
 *
 * Streaming version of the explain endpoint.
 * Uses SSE to emit steps, answer, knowledge points, and similar questions
 * as they are generated by the LLM.
 *
 * SSE event types:
 *   phase     — status transition (routing, solving, grading, done)
 *   step      — a single solution step
 *   answer    — final answer extracted
 *   knowledge — knowledge points
 *   similar   — similar questions
 *   done      — streaming complete, includes metadata
 *   error     — error occurred
 */

import { createLogger } from '@/lib/logger';
import { findSimilarQuestions } from '@/lib/solve/question-bank';
import { findSolveCacheMatches } from '@/lib/solve/solve-cache';
import { streamSolve, type StreamEvent } from '@/lib/solve/streaming-solver';
import { classifyProblem, resolveSolverModel } from '@/lib/solve/solver-constants';
import { buildKnowledgePointsPrompt } from '@/lib/solve/solver-prompts';
import { postProcessMathContent } from '@/lib/solve/math-postprocessor';
import { requireQuota, recordUsage } from '@/lib/server/billing/require-quota';
import { validateProblemSpec } from '@/lib/recognition/problem-spec-parser';

const log = createLogger('API:ExplainStream');

// ── Knowledge points generation ─────────────────────────────────────

async function generateKnowledgePoints(
  problemText: string,
  answer: string,
): Promise<{ name: string; description: string; difficulty: string }[]> {
  try {
    const { callLLM } = await import('@/lib/ai/llm');
    const { getModel } = await import('@/lib/ai/providers');
    const { parseJsonResponse } = await import('@/lib/generation/json-repair');

    const modelConfig = resolveSolverModel('universal');
    const modelWithInfo = getModel(modelConfig);
    const prompt = buildKnowledgePointsPrompt(problemText, answer);

    const result = await callLLM(
      {
        model: modelWithInfo.model,
        messages: [{ role: 'user', content: prompt }] as any,
        temperature: 0.3,
        maxOutputTokens: 1024,
      },
      'knowledge-gen',
      { retries: 1 },
      undefined,
      '你是知识点总结专家。请直接输出 JSON，不要输出其他内容。',
    );

    const parsed = parseJsonResponse<any>(result.text || '');
    if (parsed && Array.isArray(parsed.knowledgePoints)) {
      return parsed.knowledgePoints.map((k: any) => ({
        name: k.name || '',
        description: k.description || '',
        difficulty: k.difficulty || 'medium',
      }));
    }
  } catch (err) {
    log.warn('Failed to generate knowledge points:', err);
  }
  return [];
}

/**
 * Generate knowledge points from problem text only (no answer needed).
 * Runs in parallel with the main solver to save ~2s.
 */
async function generateKnowledgePointsParallel(
  problemText: string,
): Promise<{ name: string; description: string; difficulty: string }[]> {
  try {
    const { callLLM } = await import('@/lib/ai/llm');
    const { getModel } = await import('@/lib/ai/providers');
    const { parseJsonResponse } = await import('@/lib/generation/json-repair');

    const modelConfig = resolveSolverModel('universal');
    const modelWithInfo = getModel(modelConfig);

    const prompt = `你是知识点总结专家。根据题目生成2-4个相关知识点。
每个知识点description包含：核心概念+应用场景+易错点。
输出JSON：{"knowledgePoints":[{"name":"...","description":"...","difficulty":"easy|medium|hard"}]}

题目：${problemText}`;

    const result = await callLLM(
      {
        model: modelWithInfo.model,
        messages: [{ role: 'user', content: prompt }] as any,
        temperature: 0.3,
        maxOutputTokens: 1024,
      },
      'knowledge-gen-parallel',
      { retries: 0 },
      undefined,
      '你是知识点总结专家。请直接输出 JSON，不要输出其他内容。',
    );

    const parsed = parseJsonResponse<any>(result.text || '');
    if (parsed && Array.isArray(parsed.knowledgePoints)) {
      return parsed.knowledgePoints.map((k: any) => ({
        name: k.name || '',
        description: k.description || '',
        difficulty: k.difficulty || 'medium',
      }));
    }
  } catch (err) {
    log.warn('Parallel knowledge generation failed:', err);
  }
  return [];
}

// ── SSE formatting ──────────────────────────────────────────────────

function formatStreamEvent(event: StreamEvent): string {
  return `data: ${JSON.stringify(event)}\n\n`;
}

function formatSSEEvent(type: string, data: Record<string, unknown> = {}): string {
  return `data: ${JSON.stringify({ type, ...data })}\n\n`;
}

// ── POST handler ────────────────────────────────────────────────────

export async function POST(req: Request) {
  try {
    const quota = await requireQuota('llmCalls');
    if ('error' in quota) {
      return quota.error;
    }

    const body = await req.json();
    const { problem, problemImage, problemSpec: rawProblemSpec, userAnswer } = body;

    if (!problem) {
      return new Response(
        formatSSEEvent('error', { errorCode: 'MISSING_REQUIRED_FIELD', message: 'Missing required field: problem' }),
        {
          status: 400,
          headers: { 'Content-Type': 'text/event-stream' },
        },
      );
    }

    let problemSpec = null;
    if (rawProblemSpec != null) {
      try {
        problemSpec = validateProblemSpec(rawProblemSpec);
      } catch (err) {
        return new Response(
          formatSSEEvent('error', { errorCode: 'INVALID_REQUEST', message: 'Invalid problemSpec', details: err instanceof Error ? err.message : String(err) }),
          { status: 400, headers: { 'Content-Type': 'text/event-stream' } },
        );
      }
    }

    log.info(`[ExplainStream] Solving: ${problem.slice(0, 60)}...`);

    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter();
    const encoder = new TextEncoder();

    const write = async (data: string) => {
      await writer.write(encoder.encode(data));
    };

    (async () => {
      try {
        // Phase 1: Check question bank and solve cache in parallel
        await write(formatSSEEvent('phase', { phase: 'checking' }));
        const [bankMatches, cacheMatches] = await Promise.all([
          findSimilarQuestions(problem, 0.85),
          findSolveCacheMatches(problem, 0.70),
        ]);

        // Prefer question bank (higher quality) over solve cache
        if (bankMatches.length > 0) {
          const hit = bankMatches[0];
          log.info(`[ExplainStream] Question bank hit (${hit._similarity?.toFixed(2)})`);

          const processedAnswer = postProcessMathContent(hit.answer);
          await write(formatSSEEvent('step', {
            label: '解答',
            content: processedAnswer,
            keyPoints: [],
          }));
          await write(formatSSEEvent('answer', { answer: processedAnswer }));

          const kp = hit.knowledgePoints && hit.knowledgePoints.length > 0
            ? hit.knowledgePoints.map((k) => ({
                name: postProcessMathContent(k.name),
                description: postProcessMathContent(k.description),
                difficulty: k.difficulty,
              }))
            : await generateKnowledgePoints(problem, hit.answer);
          await write(formatSSEEvent('knowledge', { points: kp }));
          await write(formatSSEEvent('similar', { questions: [] }));
          await write(formatSSEEvent('done', {
            fromQuestionBank: true,
            solvingTime: 0,
          }));
          await writer.close();
          return;
        }

        if (cacheMatches.length > 0) {
          const hit = cacheMatches[0];
          log.info(`[ExplainStream] Solve cache hit`);

          const processedSolution = postProcessMathContent(hit.solution);
          await write(formatSSEEvent('step', {
            label: '解答',
            content: processedSolution,
            keyPoints: [],
          }));
          await write(formatSSEEvent('answer', { answer: processedSolution }));

          const kp = await generateKnowledgePoints(problem, hit.solution);
          await write(formatSSEEvent('knowledge', { points: kp }));
          await write(formatSSEEvent('similar', { questions: [] }));
          await write(formatSSEEvent('done', {
            fromSolveCache: true,
            solvingTime: 0,
          }));
          await writer.close();
          return;
        }

        // Phase 2: Route to agent
        const agentType = classifyProblem(problem, problemSpec);
        await write(formatSSEEvent('phase', { phase: 'routing', agentType }));

        // Phase 3: Stream solve + parallel knowledge points generation
        // Start knowledge points LLM in parallel with the main solver
        const knowledgePromise = generateKnowledgePointsParallel(problem);

        let hasAnswer = false;
        let hasKnowledge = false;
        let hasSimilar = false;
        let streamedAnswer = '';
        const streamedSteps: { label: string; content: string; keyPoints?: string[] }[] = [];
        let streamedKnowledge: { name: string; description: string; difficulty: string }[] = [];
        let streamedSimilar: { problem: string; difficulty: number; knowledgePoint: string }[] = [];
        let streamedQuestionType: 'choice' | 'fill' | 'solve' | 'judge' | undefined = undefined;
        let streamedOptions: string[] | undefined = undefined;

        for await (const event of streamSolve(agentType, problem, problemImage ?? null, problemSpec ?? null)) {
          let processedEvent = event;
          if (event.type === 'step') {
            processedEvent = {
              ...event,
              content: postProcessMathContent(event.content),
              keyPoints: (event.keyPoints ?? []).map(postProcessMathContent),
            };
          } else if (event.type === 'answer') {
            processedEvent = { ...event, answer: postProcessMathContent(event.answer) };
          } else if (event.type === 'knowledge') {
            processedEvent = {
              ...event,
              points: event.points.map((p) => ({
                ...p,
                name: postProcessMathContent(p.name),
                description: postProcessMathContent(p.description),
              })),
            };
          } else if (event.type === 'similar') {
            processedEvent = {
              ...event,
              questions: event.questions.map((q) => ({
                ...q,
                problem: postProcessMathContent(q.problem),
              })),
            };
          }
          await write(formatStreamEvent(processedEvent));
          if (processedEvent.type === 'answer') { hasAnswer = true; streamedAnswer = processedEvent.answer; }
          if (processedEvent.type === 'step') streamedSteps.push({ label: processedEvent.label, content: processedEvent.content, keyPoints: processedEvent.keyPoints });
          if (processedEvent.type === 'knowledge') { hasKnowledge = true; streamedKnowledge = processedEvent.points; }
          if (processedEvent.type === 'similar') { hasSimilar = true; streamedSimilar = processedEvent.questions; }
          if (processedEvent.type === 'metadata') {
            streamedQuestionType = processedEvent.questionType;
            streamedOptions = processedEvent.options;
          }
        }

        // Phase 4: Fill in missing sections (use parallel result if solver didn't return them)
        if (!hasAnswer) {
          await write(formatSSEEvent('answer', { answer: '' }));
        }
        if (!hasKnowledge) {
          // Use parallel knowledge generation — already running, just await result
          const kp = await knowledgePromise;
          streamedKnowledge = kp;
          await write(formatSSEEvent('knowledge', { points: kp }));
        }
        // Phase 4b: Query KB for real similar questions by knowledge point overlap
        if (streamedKnowledge.length > 0) {
          try {
            const { findSimilarByKnowledgePoints, hashProblemText } = await import('@/lib/solve/question-bank');
            const currentHash = hashProblemText(problem);
            const kbSimilar = await findSimilarByKnowledgePoints(
              problem,
              streamedKnowledge,
              currentHash,
              3,
            );
            if (kbSimilar.length >= 2) {
              streamedSimilar = kbSimilar.map((q) => ({
                problem: q.problem,
                difficulty: q.difficulty,
                knowledgePoint: q.knowledgePoint,
                answer: q.answer,
              }));
              hasSimilar = true;
              await write(formatSSEEvent('similar', { questions: streamedSimilar }));
              log.info(`[ExplainStream] KB similar questions: ${streamedSimilar.length} found`);
            }
          } catch (err) {
            log.warn('KB similar questions lookup failed:', err);
          }
        }
        if (!hasSimilar) {
          await write(formatSSEEvent('similar', { questions: streamedSimilar }));
        }

        // Phase 5: Done
        await recordUsage(quota.userId, quota.planType, 'llmCalls');
        await write(formatSSEEvent('done', {
          fromQuestionBank: false,
          agentType,
        }));

        // Auto-save to question bank and solve cache
        try {
          const { saveToQuestionBank, isProblemInBank, hashProblemText } = await import('@/lib/solve/question-bank');
          const { saveToSolveCache } = await import('@/lib/solve/solve-cache');
          const alreadyInBank = await isProblemInBank(problem);
          if (!alreadyInBank && streamedAnswer) {
            await saveToQuestionBank({
              problemText: problem,
              problemImage: problemImage ?? undefined,
              answer: streamedAnswer,
              solution: '',
              knowledgePoints: streamedKnowledge,
              similarQuestions: streamedSimilar,
              agentId: agentType,
              solvedAt: Date.now(),
              verified: false,
              questionType: streamedQuestionType,
              options: streamedOptions,
            });
          }
          if (streamedAnswer) {
            await saveToSolveCache({
              problemText: problem,
              problemHash: hashProblemText(problem),
              solution: streamedAnswer,
              agentId: agentType,
              solvedAt: Date.now(),
            });
          }
        } catch {
          // ignore save errors
        }

        await writer.close();
      } catch (err) {
        log.error('ExplainStream error:', err);
        try {
          await write(formatSSEEvent('error', {
            errorCode: 'INTERNAL_ERROR',
            message: err instanceof Error ? err.message : '解题失败',
          }));
          await writer.close();
        } catch {
          // already closed
        }
      }
    })();

    return new Response(readable, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
      },
    });
  } catch (err) {
    log.error('ExplainStream API error:', err);
    return new Response(
      formatSSEEvent('error', { errorCode: 'INTERNAL_ERROR', message: '解题失败' }),
      {
        status: 500,
        headers: { 'Content-Type': 'text/event-stream' },
      },
    );
  }
}
